import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes0')
from h import *
X=[]
X.append(r(9238842,"Galletas de mantequilla (shortbread) más saludables","Solo se necesitan unos pocos ingredientes para estas deliciosas galletas de mantequilla más saludables. ¡Su paladar se lo agradecerá!","20 (rinde aprox. 20-24 galletas según el tamaño)","1 porción",
["190 gramos de harina de almendra blanqueada superfina, aprox. 2 tazas","¼ de taza de jarabe de arce","1 cucharadita de extracto puro de vainilla (opcional)","⅛ de cucharadita de sal marina (opcional)"],
["Precaliente el horno a 325°F/162°C y cubra una bandeja para hornear con papel pergamino.","Ponga todos los ingredientes en un tazón y use una espátula de silicón para mezclar hasta que se integren. Tendrá una mezcla ligeramente desmenuzable que se mantiene unida al apretarla entre los dedos. Si la masa se siente demasiado húmeda/pegajosa, agregue más harina.","Coloque una hoja de papel pergamino sobre una tabla para cortar y la bola de masa encima. Luego coloque otra hoja de papel pergamino sobre la masa. Use un rodillo para estirar la masa de manera uniforme hasta que tenga 1/8 de pulgada de grosor.","Use un cortador de pizza para cortar la masa en forma de cuadrícula, haciendo galletas rectangulares o cuadradas. (O use los cortadores de galletas de su elección). Luego use un tenedor para hacer unos cuantos orificios en cada galleta, si lo desea.","Pase las galletas a la bandeja forrada y acomódelas en una sola capa con un poco de espacio entre cada una. Hornee de 10 a 12 minutos, hasta que los bordes estén ligeramente dorados, pero no las hornee en exceso. Estas galletas de mantequilla más saludables se sentirán blandas al salir del horno y se endurecerán cuando se enfríen a temperatura ambiente."],
["Si la masa se siente demasiado pegajosa/húmeda, agregue un poco más de harina. Si pesa la harina con una báscula de cocina, no debería necesitar agregar más. Si la masa se siente demasiado desmenuzable (debe estar ligeramente desmenuzable) y no se mantiene unida, agregue otras 1-2 cucharaditas de jarabe de arce. (De nuevo, si pesa la harina, esto no debería ocurrir). Estire la masa lo más uniformemente posible. Si algunas áreas son más delgadas o más gruesas, las galletas no se cocinarán de manera uniforme. No hornee en exceso las galletas o tendrán un sabor desagradable. Retire del horno en cuanto los bordes se vean ligeramente dorados, aprox. 10 minutos, según qué tan delgada o gruesa haya estirado la masa. Las galletas se hornean a una temperatura más baja para evitar que se quemen los bordes. ¡No se deje tentar por subir la temperatura! Las galletas estarán BLANDAS recién horneadas, así que déjelas reposar a temperatura ambiente AL MENOS 15-20 minutos antes de manipularlas. Luego, puede pasarlas a una rejilla para que sigan enfriándose, ya que se endurecerán al enfriarse."],[]))
X.append(r(9240928,"Espagueti de calabacita con parmesano vegano","¡Una versión baja en calorías del espagueti!","1 porción","1 porción",
["1 calabacita grande, en espiral (o 2 pequeñas)","1-2 cucharadas de cebolla morada (picada en cubos)","1-2 cucharadas de cebolla de verdeo (en rebanadas finas)","1-2 cucharadas de tomate (picado en cubos)","1-2 cucharadas de parmesano vegano"],
["Coloque la calabacita en espiral en una sartén y caliente a fuego medio hasta que se entibie, pero NO la cocine en exceso o quedará demasiado blanda.","Pase a un plato y cubra con las verduras y el queso parmesano vegano.","¡Disfrute!"],[],[]))
X.append(r(9244792,"Galletas veganas con doble chocolate","Las galletas veganas con doble chocolate son un postre decadente, suave, masticable y satisfactoriamente blando por dentro.","15 galletas","1 porción",
["120 gramos de harina de avena (aprox. 1 taza)","50 gramos de cacao en polvo crudo sin azúcar (aprox. 1/2 taza)","1 cucharadita de polvo para hornear","1/2 taza de crema de almendra","1/4 de taza de melaza fancy","1/4 de taza de jarabe de arce","2 cucharaditas de extracto puro de vainilla","3/4 de taza de chispas de chocolate veganas"],
["Precaliente el horno a 350℉/176℃ y cubra una bandeja para hornear con papel pergamino.","Ponga todos los ingredientes secos en un tazón mediano y bata para integrar. Luego agregue los ingredientes húmedos y revuelva hasta que no queden restos secos. Por último, incorpore con movimientos envolventes las chispas de chocolate, reservando algunas para agregarlas encima de cada galleta más adelante si lo desea.","Coloque porciones de la masa en la bandeja. Debe obtener unas 15 galletas. Luego presione suavemente cada galleta para darles ventaja para que se extiendan y presione las chispas de chocolate reservadas en cada galleta.","Hornee las galletas de 10 a 12 minutos, hasta que las bases estén ligeramente doradas, y retírelas del horno. Las galletas se sentirán blandas y a medio hornear, pero se endurecerán al enfriarse. Déjelas enfriar durante 10 minutos antes de manipularlas y pasarlas a una rejilla."],[],[]))
X.append(r(9249096,"Pan vegano de fresa y plátano [sin gluten]","Este pan vegano de fresa y plátano es un giro divertido a su receta clásica, ¡ligeramente dulce y completamente delicioso!","12 porciones","1 rebanada",
[("Ingredientes húmedos","1 taza colmada de plátano maduro machacado, aprox. 3 plátanos grandes"),("Ingredientes húmedos","⅓ de taza de compota de manzana sin azúcar"),("Ingredientes húmedos","¼ de taza de jarabe de arce"),("Ingredientes húmedos","2 cucharaditas de extracto puro de vainilla"),("Ingredientes húmedos","1 taza de fresas picadas en cubos, frescas o congeladas"),("Ingredientes secos","2 tazas de harina de avena o harina multiusos"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","1 cucharadita de canela"),("Ingredientes secos","½ cucharadita de bicarbonato de sodio")],
["Precaliente el horno a 375℉/190℃ y cubra un molde para pan con papel pergamino. (O engrásalo si no evita el aceite).","En un tazón grande, machaque los plátanos. Luego agregue la compota de manzana, el jarabe de arce y la vainilla y mezcle bien.","Al mismo tazón, agregue todos los ingredientes secos y mezcle hasta que se integren. Luego incorpore suavemente con movimientos envolventes las fresas. La masa será espesa.","Vierta la masa en el molde para pan preparado y agregue encima algunas rebanadas de fresa y de plátano, si lo desea.","Hornee de 50 a 60 minutos, o hasta que un palillo insertado en el centro del pan salga limpio. Retírelo del horno y déjelo enfriar durante 10 minutos antes de pasar el pan dulce a una rejilla durante al menos 20 minutos antes de rebanarlo."],
["Use plátanos muy maduros. Cuantas más manchas cafés, mejores y más dulces serán los resultados. Como esta receta usa muy poco endulzante, debe asegurarse de que los plátanos aporten suficiente dulzor.","Mida los plátanos machacados. Los plátanos varían de tamaño. Por eso, use suficiente puré de plátano para lograr el dulzor y la humedad óptimos. Mida para asegurarse de que usa una taza colmada de plátano machacado.","Use papel pergamino para cubrir el molde para pan. Aunque un molde antiadherente funciona, es más fácil pasar el pan del molde cuando se usa papel pergamino, sin romperlo.","Cada horno es diferente. Por eso, compruebe el punto de cocción del pan de fresa y plátano con un palillo o cuchillo insertado en el centro. Cuando salga seco, estará listo.","Deje que se enfríe. Dé tiempo adicional para que el pan se enfríe. Al menos 10 minutos antes de pasarlo, y otros 20 minutos en la rejilla para ayudar a que se asiente. Esto hace que sea mucho más fácil rebanarlo.","Las sobras se conservan bien envueltas a temperatura ambiente de 2 a 3 días, en el refrigerador de 3 a 5 días o congeladas (una vez frías) en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9249680,"Panqueques veganos de calabaza [integrales]","Los panqueques veganos de calabaza con especias son gruesos, esponjosos y deliciosos. Perfectos para el otoño y para todos los amantes de las especias de calabaza.","12 panqueques de 4\"","1 panqueque",
["1 taza de leche de soya","1 cucharadita de vinagre de manzana","1 ¼ tazas de harina integral","1 cucharada de polvo para hornear","1 cucharadita de canela","½ cucharadita de jengibre molido","¼ de cucharadita de nuez moscada molida","¼ de cucharadita de clavo molido","⅓ de taza de puré de calabaza","2 cucharadas de jarabe de arce","2 cucharadas de compota de manzana sin azúcar","1 cucharadita de vainilla"],
["Precaliente la plancha y luego, en un tazón pequeño, combine la leche de soya y el vinagre de manzana. Reserve para que se cuaje.","En un tazón grande, bata la harina, el polvo para hornear, la canela, el jengibre, la nuez moscada y el clavo. Una vez mezclados, agregue el puré de calabaza, el jarabe de arce, la compota de manzana, la vainilla y la leche ya cuajada. Mezcle hasta que se integren, sin mezclar en exceso.","Vierta aproximadamente 1/4 de taza de masa sobre la plancha caliente, dejando mucho espacio entre cada panqueque.","Cocine hasta que se hayan formado pequeñas burbujas en la superficie de los panqueques y los bordes estén dorados, aprox. 5-6 minutos. Luego voltee y cocine otros 3-5 minutos hasta que estén dorados.","Sirva con nueces pecanas picadas, rebanadas de plátano, jarabe de arce, mermelada de arándano azul y chía, o frutos rojos."],
["Si no tiene todas las especias indicadas, pero tiene especias para pay de calabaza, puede usar 2 cucharaditas de esas especias para sustituir los cuatro condimentos. No mezcle en exceso la masa de los panqueques de calabaza. Como la mayoría de las recetas de panqueques, unos cuantos grumos están perfectamente bien, así que mezcle hasta que apenas se integre. Asegúrese de que la plancha esté CALIENTE antes de cocinar los panqueques. Como no usamos aceite, necesita una superficie caliente para evitar que se peguen. Pruebe el calor agregando una gota de agua para ver si chisporrotea. Si no tiene o no le gusta la calabaza, puede usar en su lugar puré de camote o de calabaza butternut. Una vez fríos, puede refrigerar las sobras de 2 a 3 días, o congelarlas hasta por 1 mes. Asegúrese de dejar enfriar los panqueques antes de congelarlos."],[]))
X.append(r(9250282,"Mayonesa vegana sin aceite","La mayonesa vegana casera es fácil de preparar, toma 5 minutos o menos y es tan sabrosa como la comprada. ¡Sin huevo, sin aceite, sin lácteos, sin soya y sin frutos secos!","16 porciones de 1 cucharada (rinde aprox. 1 taza)","1 porción",
["1 taza de semillas de calabaza crudas sin cáscara o pepitas","⅓ de taza de agua fresca, o un poco más si desea una mayonesa más ligera","1 cucharada de vinagre de manzana","1 cucharada de jugo de limón","1 cucharadita de mostaza amarilla","½ cucharadita de cebolla en polvo","½ cucharadita de sal marina o al gusto","⅛ de cucharadita de sal negra (opcional, pero recomendada)"],
["Ponga las semillas de calabaza en la licuadora y procese hasta que se deshagan y tengan una consistencia como de harina.","Ahora agregue todos los demás ingredientes y procese hasta que quede suave y cremosa.","Refrigere hasta el momento de usar, ya que sabe mejor fría."],
["Procesar primero las semillas por separado ayudará a asegurar que no queden trozos sueltos de semillas en la mayonesa, lo que resultará en una mayonesa más suave. Guarde en un recipiente hermético en el refrigerador hasta por 1 semana. Si no evita los frutos secos y desea que la mayonesa sea blanca, puede sustituir las semillas de calabaza por anacardos (nueces de la India). Si no tiene una licuadora de alta potencia, deberá remojar primero los anacardos en agua hirviendo durante al menos 15 minutos. Para una mayonesa picante, agregue un poco de salsa picante o cayena, o consulte mi mayonesa de Sriracha."],[]))
X.append(r(9251879,"Sopa de brócoli y almendra","Una sopa cremosa de brócoli y almendra, hecha en una sola olla o sartén, aterciopelada, rica en proteínas y deliciosa.","6 porciones","1 porción",
["1 taza de almendras blanqueadas *si no tiene almendras blanqueadas, vea las notas o arriba las instrucciones para blanquearlas","1 cebolla amarilla picada en trozos grandes","3 dientes de ajo pelados y picados","2 tallos de apio picados en trozos grandes","¾ de cucharadita de tomillo seco","1.5 libras de papas Yukon Gold o blancas, aprox. 3.5 tazas en cubos","7 tazas de floretes de brócoli, aprox. 1 brócoli grande","5 tazas de caldo de verduras bajo en sodio","½ cucharadita de sal marina o al gusto","½ cucharadita de pimienta negra o al gusto"],
["Si no tiene almendras blanqueadas, comience blanqueando almendras crudas enteras siguiendo las instrucciones de la publicación, o vea el resumen en las notas a continuación.","Pique en trozos grandes la cebolla, el ajo y el apio y póngalos en una olla con 2-3 cucharadas de agua. Saltee de 3 a 4 minutos, hasta que se ablanden, agregando más agua para evitar que se peguen, si es necesario. Luego agregue el tomillo y saltee durante 30 segundos, hasta que desprenda aroma.","Vierta el caldo, las almendras, las papas picadas, los floretes de brócoli y la sal y la pimienta. Hierva a fuego alto y luego baje el fuego a medio y cocine durante aprox. 6-8 minutos, hasta que las papas estén tiernas al pincharlas con un tenedor.","Use una batidora de inmersión para hacer un puré con la sopa, o pásela con cuidado a una licuadora de vaso, trabajando por tandas. Tenga precaución al manipular líquidos calientes y no llene demasiado la licuadora. Sirva con pan crujiente, crotones y/o perejil fresco."],
["Use caldo de verduras bajo en sodio O omita la sal si solo tiene caldo regular.","Para hacer puré la sopa, use una batidora de inmersión o de mano para ensuciar menos y facilitar la mezcla en un solo paso.","Si no tiene una batidora de mano, pase con mucho cuidado a una licuadora de vaso. Trabaje por tandas, según sea necesario, y nunca llene demasiado la licuadora con líquidos calientes.","Una vez hecha puré, pruebe la sopa y ajuste la sal y la pimienta a su gusto. Recuerde que siempre puede agregar, pero no puede quitar.","Esta sopa es fantástica como sobras y espesa más al reposar, así que es ideal para prepararla con anticipación y recalentarla.","Las sobras se conservan en el refrigerador hasta por 4 días o puede congelarlas hasta por 3 meses.","Cómo blanquear almendras. Si no tiene almendras blanqueadas, solo necesita 5 minutos para prepararlas a partir de almendras crudas enteras. Hierva una olla pequeña con agua (suficiente para cubrir las almendras). Cuando hierva, agregue las almendras y hierva durante 1 minuto. Luego escurra y enjuague con agua fría para enfriarlas lo suficiente para manipularlas. Luego apriete las almendras y la piel se desprenderá fácilmente."],[]))
X.append(r(9252979,"Muffins de plátano y lentejas","Deliciosos y nutritivos muffins de plátano y lentejas que encantarán tanto a adultos como a niños.","12 muffins","1 porción",
["1 taza de lentejas verdes cocidas o de lata (aprox. ⅓ de taza en seco)","1 taza de plátano machacado, de aprox. 3 plátanos medianos","½ taza de compota de manzana sin azúcar","2 cucharaditas de extracto puro de vainilla","150 gramos de harina integral para repostería, aprox. 1 + ⅓ de taza","2 cucharaditas de polvo para hornear","½ cucharadita de canela","1 taza de arándanos azules frescos"],
["Precaliente el horno a 350℉/176℃ y cubra un molde para muffins con capacillos de papel pergamino.","Ponga las lentejas cocidas, el plátano machacado, la compota de manzana y la vainilla en la licuadora y procese hasta que quede completamente suave. Luego vierta la mezcla en un tazón mediano.","Al mismo tazón, agregue la harina, el polvo para hornear y la canela, y mezcle hasta que apenas se integren. Luego incorpore con movimientos envolventes los arándanos azules.","Reparta la mezcla en los 12 moldes para muffins y hornee de 20 a 22 minutos, o hasta que un palillo insertado en el centro de un muffin salga casi limpio.","Retire el molde del horno y deje reposar los muffins de lentejas a temperatura ambiente durante 10 minutos antes de pasarlos a una rejilla."],
["Use plátanos muy maduros con muchas manchas cafés en la cáscara para obtener más dulzor. También puede usar plátanos congelados; solo deje que lleguen a temperatura ambiente antes de machacarlos.","Use polvo para hornear FRESCO + ACTIVO. El polvo para hornear que lleva abierto en la despensa 6 meses o más puede empezar a perder su efectividad.","No mezcle en exceso. La textura de los muffins queda mejor cuando se incorporan los ingredientes con movimientos envolventes hasta que apenas se integren.","Golpee suavemente el molde para muffins sobre una superficie dura para cerrar cualquier hueco en la masa antes de hornear.","Deje reposar los muffins 10 minutos después de hornearlos. Este breve tiempo de enfriamiento permitirá que los muffins se asienten por completo y evitará que se rompan al sacarlos del molde."],[]))
X.append(r(9254108,"Tofu en freidora de aire","Tofu crujiente en freidora de aire lleno de sabor, bajo en calorías y grasa, sin aceite pero absolutamente delicioso. Crujiente por fuera, suave y tierno por dentro.","4 porciones","1 porción",
["350 gramos (12 onzas) de un bloque de tofu extra firme (de preferencia no transgénico)","2 cucharadas de tamari o salsa de soya si no evita el gluten","1 cucharada de vinagre de arroz","1 cucharada de fécula de maíz","1 cucharadita de ajo en polvo","1 cucharadita de cebolla en polvo","1 cucharadita de pimentón ahumado o dulce","¼ de cucharadita de sal marina (opcional)"],
[("Prense el tofu","Corte el tofu en cubos de media pulgada. Luego coloque unas toallas de papel o un paño de cocina limpio sobre una tabla para cortar y ponga encima los cubos de tofu en una sola capa. Ahora agregue más toallas de papel sobre los cubos y coloque encima otra tabla para cortar, un plato plano o una bandeja para hornear. Por último, coloque algo muy pesado encima, como una sartén de hierro fundido o un libro pesado. Prense así durante 15 minutos mientras prepara los demás ingredientes."),("Prepare el tofu","Combine todos los condimentos secos, incluida la fécula de maíz, en un tazón pequeño y reserve."),("Prepare el tofu","Coloque los cubos de tofu prensados en un recipiente poco profundo o contenedor y vierta el tamari y el vinagre de arroz encima; mezcle para cubrir de manera uniforme. Luego espolvoree todos los condimentos encima y mezcle bien. Si usa un contenedor, puede ponerle la tapa y girarlo suavemente para distribuir los condimentos de manera uniforme."),("Prepare el tofu","Acomode los cubos en la canasta de la freidora en una sola capa, trabajando en dos tandas si tiene una freidora pequeña. No amontone el tofu para asegurar el máximo crujiente. Cocine en la freidora de aire a 400 grados F durante 10-15 minutos, mezclando o sacudiendo la canasta a la mitad del tiempo. El mío quedó perfecto a los 13 minutos, pero comience a revisar el tofu alrededor de los 10 minutos."),("Prepare el tofu","Sirva con un dip como mayonesa picante o crema de anacardos (nueces de la India). O úselo para cubrir arroz y verduras.")],
["No amontone el tofu, o no quedará tan crujiente. Si tiene una freidora más pequeña, trabaje en dos tandas para obtener la mejor textura y resultados. Si trabaja por tandas, recuerde que la segunda tanda se cocinará más rápido porque la freidora ya está caliente, así que comience a revisar el tofu antes. Haga lo posible por cortar los cubos en trozos de tamaño similar para una cocción uniforme y los mejores resultados. Planee consumir el tofu de la freidora de aire el mismo día en que se prepara, ya que empezará a perder lo crujiente cuanto más tiempo repose. Si el tiempo lo permite, puede dejar el tofu en el adobo de 30 minutos hasta 12 horas (en refrigeración) antes de cocinarlo en la freidora de aire, para que absorba aún más sabor."],[]))
X.append(r(9255743,"Alitas buffalo veganas de coliflor [horno o freidora de aire]","Las alitas buffalo de coliflor son picantes, deliciosas y sabrosas. ¡Crujientes por fuera, tiernas por dentro, el bocadillo perfecto para el día del juego!","4 porciones","1 porción",
["1 coliflor pequeña cortada en floretes pequeños, de un bocado","½ taza de harina de arroz integral o la harina de su elección si no evita el gluten","1 cucharadita de ajo en polvo","1 cucharadita de cebolla en polvo","1.5 cucharaditas de pimentón","½ cucharadita de comino","½ cucharadita de sal marina","¼ de cucharadita de pimienta negra","¼ de cucharadita de pimienta de cayena","¾ de taza de leche de anacardos (nueces de la India) sin azúcar o la leche que prefiera",("Ingredientes de la salsa de alitas buffalo","½ taza de agua"),("Ingredientes de la salsa de alitas buffalo","¼ de taza de vinagre blanco"),("Ingredientes de la salsa de alitas buffalo","1 cucharadita de pimentón"),("Ingredientes de la salsa de alitas buffalo","1 cucharadita de ajo en polvo"),("Ingredientes de la salsa de alitas buffalo","¼ de cucharadita de pimienta de cayena"),("Ingredientes de la salsa de alitas buffalo","½ cucharadita de sal marina"),("Ingredientes de la salsa de alitas buffalo","3 cucharadas de pasta de tomate"),("Salsa opcional para mojar (muy recomendada)","1 receta de aderezo ranch sin lácteos")],
["Si va a preparar la salsa ranch para mojar, comience poniendo a remojar los anacardos (nueces de la India) antes de empezar a preparar la coliflor. Una vez remojados, prepare el ranch según sus instrucciones y refrigere hasta que lo necesite.","Cubra una bandeja para hornear con papel pergamino y precaliente el horno a 450 grados F.","Coloque la coliflor cortada en un tazón grande. Luego, en otro tazón, combine la harina y todos los condimentos y mezcle para integrar. Luego agregue la leche y mezcle bien para hacer la masa. Ahora vierta la masa en el tazón con la coliflor y mezcle bien para cubrir cada pieza de manera uniforme.","Coloque la coliflor cubierta en la bandeja preparada, una pieza a la vez, en una sola capa y hornee durante 20 minutos. Voltee una vez a la mitad del tiempo.","Mientras tanto, prepare la salsa de alitas buffalo poniendo todos sus ingredientes en una cacerola pequeña. Bata para integrar y cocine a fuego lento a temperatura media de 3 a 5 minutos, dejando que los sabores se integren.","Retire la coliflor del horno y cubra los bocados con la salsa buffalo. Yo uso una brocha de silicón para untar cada pieza de coliflor con una cantidad generosa de salsa. Luego regrese al horno durante 10-15 minutos, volteando una vez a la mitad del tiempo.","Sirva con ranch y moje a más no poder.",("Instrucciones para freidora de aire","Coloque la coliflor cortada en un tazón grande. Luego, en otro tazón, combine la harina y todos los condimentos y mezcle para integrar. Luego agregue la leche y mezcle bien para hacer la masa. Ahora vierta la masa en el tazón con la coliflor y mezcle bien para cubrir cada pieza de manera uniforme."),("Instrucciones para freidora de aire","Coloque la coliflor cubierta en la canasta crujiente, dentro del aparato Ninja Foodi. Luego programe a 390 grados F y cocine en la freidora de aire durante 20 minutos, sacudiendo la canasta cada 5 minutos aproximadamente."),("Instrucciones para freidora de aire","Mientras tanto, prepare la salsa de alitas buffalo poniendo todos sus ingredientes en una cacerola pequeña. Bata para integrar y cocine a fuego lento a temperatura media de 3 a 5 minutos, dejando que los sabores se integren."),("Instrucciones para freidora de aire","Luego use una brocha de silicón para cubrir de manera uniforme los floretes con la salsa buffalo. Continúe cocinando en la freidora de aire otros 10-15 minutos, sacudiendo o volteando los floretes a la mitad del tiempo. El tiempo de cocción variará según el modelo de freidora de aire que use y el tamaño de los floretes."),("Instrucciones para freidora de aire","Sirva con ranch y moje a más no poder.")],
["Si usa el aderezo ranch, prepárelo primero y refrigere hasta que lo necesite. Para una versión sin frutos secos, use leche de soya o de avena en lugar de la de anacardos. Las sobras se pueden guardar en el refrigerador de 2 a 3 días y recalentar en la freidora de aire, el horno o el horno tostador. ¡Consejos de expertos para los MEJORES resultados, siempre! Después de cubrir las alitas buffalo de coliflor con la masa, no las vierta de golpe sobre la bandeja para hornear. El exceso de masa en el fondo del tazón se acumulará en la bandeja, haciendo que los bocados se peguen entre sí y al papel pergamino. Esto hará que queden menos crujientes.","Sé que es tedioso, pero para obtener los mejores resultados, coloque las alitas buffalo veganas en la bandeja para hornear, una pieza a la vez.","Asegúrese de que las alitas buffalo veganas estén en una sola capa, con espacio entre cada una. Esto ayudará a que queden más crujientes.","Voltee la coliflor a la mitad de la primera Y de la segunda ronda (después de cubrirla con la salsa buffalo) de horneado. Esto ayuda a obtener el máximo crujiente de estos deliciosos bocados buffalo."],[]))
